from lib import *
S = SS('w63')
steps = [
    step("时间戳选项(kind 8,长度 10:TSval 4 字节 + TSecr 4 字节,前面补两个 NOP 凑成 12 字节)。lo0 上 SYN 和 SYN+ACK 里都有,SYN 的 TSecr 是 0;example.com 的 SYN+ACK 里也有(两边都带才启用)。代价是每个数据段的 TCP 头从 20 字节变成 32 字节:lo0 的 MSS 是 16344,数据段里观察到的最大载荷是 16332 字节 = 16344 − 12。example.com 的 SYN+ACK 里 MSS 是 1400。", t=tl(S(1)), mark=lidx(S(1), 'lo0:SYN 里 TSval=True', '所以 lo0 上 MSS'), done=lidx(S(1), 'example.com:本机 SYN 里 TS=True'), kv=KV([['选项', 'kind 8,10 字节 + 2 NOP = 12 字节'], ['协商', '两端的 SYN 都带才启用'], ['lo0 载荷', '16344 − 12 = 16332 字节']], ['lo0 载荷'])),
    step("时间戳的“钟”:连接空闲,用 keepalive(idle=1、intvl=1)让客户端每秒发一个探测、服务端回 ACK。服务端回的 9 个 ACK 都带时间戳,TSval 相邻差值是 [1001, 1000, 1000, 1000, 1001, 1001, 1001, 1001]——每秒增加约 1000,即 1000 Hz,一个刻度 1.00 ms,32 位 TSval 绕一圈要 49.7 天(计算)。有两个有意思的现象:客户端发出的 9 个 keepalive 探测一个都不带时间戳选项(头长 20 字节),所以服务端回的 ACK 里 TSecr 一直是同一个值;net.inet.tcp.randomize_timestamps = 1,每条连接的 TSval 起点加随机偏移,绝对值没有意义。example.com 一侧:本机握手后发出的 6 个纯 ACK(探测)同样 0 个带时间戳;服务器发来的 9 个带时间戳的包,TSval 变化速率 1000.1 Hz,也是 1 ms 一个刻度。", t=tl(S(2)), mark=lidx(S(2), '客户端发出的 keepalive 探测', '服务端 TSval 的变化', '服务端 ACK 里的 TSecr'), done=lidx(S(2), '本机的时间戳钟', 'example.com:握手之后', '服务器 TSval 随时间变化的速率'), b=bars([['本机时间戳钟', 1000.0, '1000.0 Hz'], ['example.com 服务器', 1000.1, '1000.1 Hz']], 1000.1, mark=[], done=[0, 1]), kv=KV([['本机', '1000.0 Hz,1.00 ms 一刻度'], ['example.com', '1000.1 Hz'], ['keepalive 探测', '不带时间戳选项(头 20 字节)'], ['回绕', '2^32 ÷ 1000 Hz = 49.7 天(计算)']], ['keepalive 探测'])),
    step("用时间戳量往返时间:lo0 上 netlab 每方向延迟 50 ms,发 20 条小消息(间隔 150 ms)。对每个数据段,找服务端第一个 TSecr 等于它的 TSval 的 ACK,两者被抓到的时间差:20 个段全部配对成功,中位 50.0 ms(最小 49.5 / 最大 51.1)。但内核自己的 tcp_info 给出 rttcur = 100 ms、srtt = 93 ms、rttvar = 13 ms。抓包得到的只有一半:我的推断是 dummynet 的延迟有一部分发生在抓包点之外,抓包只看到每个包一次,所以 ACK 的返程延迟没有算进去。用 TSecr 配对本身没有问题(20/20),但要得到真实 RTT 必须在发送端内核里量,不能拿一个抓包点的两次时间相减。", t=tl(S(3)), mark=lidx(S(3), '数据段第一次被抓到 → 对应 ACK 第一次', '内核 tcp_info'), done=lidx(S(3), '凭 TSecr 配对成功', '数据段第一次被抓到 → 对应 ACK 最后一次'), b=bars([['抓包配对 RTT(中位)', 50.0, '50.0 ms'], ['内核 rttcur', 100, '100 ms'], ['内核 srtt', 93, '93 ms']], 100, mark=[0], done=[1, 2]), kv=KV([['TSecr 配对', '20 / 20 成功'], ['抓包差值', '50.0 ms(一个方向)'], ['tcp_info', 'rttcur 100 ms / srtt 93 ms']], ['抓包差值'])),
    step("重传的歧义(Karn 问题):丢包 20%、延迟 20 ms,发 150 个小消息。150 个数据段里有 36 个被重传(同一序号出现不同的 TSval),例如序号 24194 发了 2 次,TSval 分别是 3326993437 和 3326993503;序号 24294 的两次间隔 90 ms。在这 36 个被重传的段里,有 34 个能找到一个 ACK 的 TSecr 等于某次重传的 TSval,而 TSecr 等于最初那次 TSval 的是 0 个。没有时间戳时,发送方收到这些 ACK 分不清是对原包还是重传包的回应,Karn 算法只好丢掉这些 RTT 样本;有了时间戳,TSecr 直接告诉你是哪一次发送,可以放心采样。", t=tl(S(4)), mark=lidx(S(4), '被重传', '有 ACK 回显了某次重传'), done=lidx(S(4), '序号 24194', '序号 24294', '序号 24344'), b=bars([['数据段', 150, '150'], ['被重传', 36, '36'], ['ACK 回显重传的 TSval', 34, '34'], ['ACK 回显最初的 TSval', 0, '0']], 150, mark=[2], done=[0, 1, 3]), kv=KV([['被重传的段', '36 / 150'], ['ACK 回显重传 TSval', '34 个'], ['ACK 回显最初 TSval', '0 个'], ['意义', '分得清 ACK 对应哪次发送']], ['意义'])),
    step("PAWS(防止回绕的序号)只能给计算,没有实测:它的规则是“收到的段的 TSval 比本连接记录的最近值 ts_recent 还小(按 32 位回绕比较),就丢掉”,要验证需要往连接里注入旧报文,这需要原始套接字,这里做不到。需要它的原因是序号 32 位会回绕:2^32 字节在 100 Mbit/s 的链路上 343.6 秒回绕一次,1000 Mbit/s 上 34.4 秒,10000 Mbit/s 上 3.4 秒,100000 Mbit/s 上 0.3 秒——比一个旧包在网络里能活的时间还短时,旧包的序号就可能被误当成新数据。时间戳钟 1000 Hz 时,TSval 要 49.7 天才回绕,PAWS 的比较窗口(2^31)是 24.9 天,远大于包的寿命,所以可以靠 TSval 把旧包挡掉。(全部是计算值。)", t=tl(S(5)), mark=lidx(S(5), '时间戳钟 1000 Hz'), done=lidx(S(5), '100 Mbit/s 的链路上', '1000 Mbit/s 的链路上', '10000 Mbit/s 的链路上', '100000 Mbit/s 的链路上'), b=bars([['100 Mbit/s', 343.6, '343.6 秒'], ['1 Gbit/s', 34.4, '34.4 秒'], ['10 Gbit/s', 3.4, '3.4 秒'], ['100 Gbit/s', 0.3, '0.3 秒']], 343.6, mark=[], done=[0, 1, 2, 3]), kv=KV([['序号回绕', '2^32 字节 ÷ 带宽(计算)'], ['TSval 回绕', '49.7 天(1000 Hz,计算)'], ['PAWS', '没有实测(需要注入旧报文)']], ['PAWS'])),
]
A = mkartw('w63', 63, '网络协议,TCP,时间戳,TSval,TSecr,PAWS,RTT,Karn,真实验证,动画演示',
    '实测 TCP 时间戳选项:占 12 字节(lo0 载荷 16344−12=16332);时钟 1000 Hz;keepalive 探测不带时间戳;TSecr 配对 20/20 成功但抓包差值只是一半 RTT(50 对 100 ms);重传的 36 个段里 34 个 ACK 回显重传的 TSval,分得清是哪次发送;PAWS 只有计算。',
    'TCP 时间戳选项一箭双雕:让发送方在重传存在时仍能放心测 RTT,又让接收方能挡掉绕了一圈回来的旧包(PAWS)。这篇在 macOS 上抓包看它的格式、开销、时钟,用 TSecr 配对测 RTT,在丢包里验证 ACK 回显的是哪一次发送。PAWS 的注入验证做不到,只给计算。',
    [('1000 Hz', '本机与 example.com 服务器的时间戳钟:1 ms 一个刻度,49.7 天回绕'), ('34 / 36', '被重传的段里,有 ACK 回显了重传那次的 TSval 的个数'), ('50 vs 100 ms', '单个抓包点用 TSecr 配对读到的 RTT 与内核 rttcur 的差别')],
    [('格式与开销', '<p>kind 8、10 字节加两个 NOP 共 12 字节,两端 SYN 都带才启用;lo0 上有效载荷从 MSS 16344 变成 16332。</p>'),
     ('时钟', '<p>回 ACK 的一端 TSval 每秒增加约 1000;每条连接起点有随机偏移。keepalive 探测不带时间戳。</p>'),
     ('用 TSecr 量 RTT', '<p>TSecr 配对 20/20 成功,但单个抓包点读到的差值不是真正 RTT(50 对 100 ms)。</p>'),
     ('Karn 问题', '<p>36 个被重传的段中,34 个 ACK 回显重传的 TSval,发送方因此分得清 ACK 对应哪次发送。</p>'),
     ('PAWS', '<p>序号 32 位回绕:10 Gbit/s 下 3.4 秒。TSval 49.7 天才回绕,可以挡掉旧包。没有实测。</p>')],
    steps,
    [ENV_W + '。第一、二、三、四节在 lo0 和 en0 抓包;第三、四节用 netlab(每方向 50 ms 与 20 ms,丢包 0% 与 20%);抓包点读到的 RTT 只有一半的解释是推断;重传数量随机,每次运行不同',
     '没有验证:PAWS 的实际丢包行为(需要注入旧报文,没有原始套接字);关闭时间戳(本机没有找到对应的 sysctl)后的行为;TSval 起点随机偏移的范围;kernel 内部如何用 TSecr 量 RTT(只从抓包侧配对);时间戳泄露开机时间的隐私问题(randomize_timestamps=1 正是对它的缓解,但没有测试其它系统)'],
    '时间戳与 PAWS')
